<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { getModels, historicalPredict } from '@/api/ml'
import { getTrack, getTyphoon, getTyphoons } from '@/api/typhoons'
import type { BacktestResult, ModelArtifact } from '@/types/ml'
import type { Observation, TyphoonEvent } from '@/types/typhoon'
import { numberText, utc } from '@/utils/typhoon'
const route=useRoute(), models=ref<ModelArtifact[]>([]), events=ref<TyphoonEvent[]>([]), points=ref<Observation[]>([]), modelId=ref(''), eventId=ref<number>(), forecastTime=ref(''), result=ref<BacktestResult>(), query=ref(''), loading=ref(false)
const candidates=computed(()=>{const by=new Map(points.value.map(p=>[new Date(p.observation_time).getTime(),p]));return points.value.filter(p=>{const t=new Date(p.observation_time).getTime();return [0,6,12,18].every(h=>by.get(t-h*3600000)?.cma_wind_ms!=null)}).map(p=>p.observation_time)})
async function search(){const response=await getTyphoons({page:1,page_size:100,sort_by:'season',sort_order:'desc',source:'ibtracs',include_spurs:false,name:query.value||undefined});events.value=response.items}
async function loadTrack(){result.value=undefined;forecastTime.value='';if(eventId.value){const r=await getTrack(eventId.value,'MAIN');points.value=r.items}}
async function predict(){if(!modelId.value||!eventId.value||!forecastTime.value)return;loading.value=true;try{result.value=await historicalPredict({model_id:modelId.value,typhoon_id:eventId.value,forecast_time:forecastTime.value});ElMessage.success('真实模型历史回测完成')}catch(e:any){ElMessage.error(e.response?.data?.message||'无法构建有效历史输入')}finally{loading.value=false}}
onMounted(async()=>{models.value=await getModels();modelId.value=models.value[0]?.id??'';await search();const fromRoute=Number(route.query.typhoon_id);if(fromRoute){if(!events.value.some(e=>e.id===fromRoute)){const detail=await getTyphoon(fromRoute);events.value.unshift(detail)}eventId.value=fromRoute;await loadTrack()}})
</script>
<template><section class="page-stack"><div class="page-heading"><div><h2>强度预测</h2><p>历史起报时刻回测 · 预测未来 6 小时 CMA 最大持续风速</p></div></div><el-alert title="历史回测预测" description="仅使用起报时刻及之前四个连续时次；目标时刻真实值只在预测完成后用于对照，不进入输入。结果不是实时业务预报。" type="warning" :closable="false" show-icon/><el-card shadow="never" class="data-card"><el-form label-position="top" class="prediction-form"><el-form-item label="已训练模型"><el-select v-model="modelId" placeholder="没有可用模型"><el-option v-for="m in models" :key="m.id" :value="m.id" :label="`${m.name} · ${m.model_type.toUpperCase()}`"/></el-select></el-form-item><el-form-item label="搜索历史台风"><el-input v-model="query" placeholder="输入名称，如 MERANTI" @keyup.enter="search"><template #append><el-button @click="search">搜索</el-button></template></el-input></el-form-item><el-form-item label="历史台风"><el-select v-model="eventId" filterable placeholder="选择台风" @change="loadTrack"><el-option v-for="e in events" :key="e.id" :value="e.id" :label="`${e.season} · ${e.name} · ${e.sid}`"/></el-select></el-form-item><el-form-item label="有效起报时间（UTC）"><el-select v-model="forecastTime" filterable placeholder="选择具备连续历史窗口的时刻"><el-option v-for="t in candidates" :key="t" :value="t" :label="utc(t)"/></el-select></el-form-item></el-form><el-empty v-if="!models.length" description="尚无训练成功并保存的模型，请先在模型训练页面创建实验"/><el-alert v-else-if="eventId&&candidates.length===0" title="该台风没有完整的四时次历史输入" type="info" :closable="false"/><el-button type="primary" :loading="loading" :disabled="!modelId||!eventId||!forecastTime" @click="predict">执行真实模型推理</el-button></el-card><el-card v-if="result" shadow="never" class="data-card"><template #header><div class="card-header"><strong>{{result.name}} · {{result.sid}}</strong><el-tag type="warning">历史回测</el-tag></div></template><el-descriptions :column="3" border><el-descriptions-item label="起报时间">{{utc(result.forecast_time)}}</el-descriptions-item><el-descriptions-item label="目标时间">{{utc(result.target_time)}}</el-descriptions-item><el-descriptions-item label="模型">{{result.model_name}}</el-descriptions-item><el-descriptions-item label="预测风速">{{numberText(result.predicted_wind)}} m/s</el-descriptions-item><el-descriptions-item label="历史真实风速">{{result.actual_wind==null?'目标时次无可靠标签':numberText(result.actual_wind)+' m/s'}}</el-descriptions-item><el-descriptions-item label="预测误差">{{result.error==null?'不可计算':numberText(result.error)+' m/s'}}</el-descriptions-item><el-descriptions-item label="输入风速" :span="3">{{result.input_winds.map(v=>numberText(v)).join(' → ')}} m/s</el-descriptions-item><el-descriptions-item label="数据来源" :span="3">{{result.data_source}} · {{result.quality_profile}}</el-descriptions-item></el-descriptions></el-card></section></template>
